#!/usr/bin/env python
"""Deterministic builder for the committed synthetic V9 universe-audit fixture.

OWNER: lane A3, cycle MARKET-DATA-PLANE-V2R1 (plan D2 remediation).

WHAT THIS DIR IS
----------------
A repo-authored SYNTHETIC fixture (classes SYNTHETIC_HAND_COMPUTED for the
market/funding inputs and SCHEMA_MINIMAL for the pinned-manifest replica) that
lets the V9 audit ENGINE run without any host data.  It contains NO real
provider payload: every bar, funding rate, instrument definition and volume
number below is a small synthetic value chosen so that every census, gap run
and completeness verdict is hand-computable.

LAYOUT (all paths relative to this directory)
---------------------------------------------
  pinned_selection_manifest.json   SCHEMA_MINIMAL replica of
                                   data/v8x_manifests/crypto_universe_selection.json
                                   (schema_version "2.0.0"-shaped; 10 synthetic
                                   chosen alts + BTCUSDT benchmark context;
                                   candidates_evaluated carries exact decimal
                                   volume strings)
  catalog_root/data/binance_bar/<SYM>-PERP.BINANCE-15-MINUTE-LAST-EXTERNAL/*.parquet
                                   synthetic bars: columns ts_event int64 NS,
                                   quote_volume string, one row per 15m slot
  catalog_root/data/crypto_perpetual/<SYM>-PERP.BINANCE/instrument-0001.parquet
                                   columns id (string) + info (binary JSON:
                                   quoteAsset USDT, contractType PERPETUAL,
                                   status TRADING, onboardDate =
                                   scored-start - 400d, exchangeInfo-shaped
                                   filters with tickSize/stepSize/minNotional)
  funding/<SYM>/funding.json       {"symbol", "rows"}: complete 8h settlements
                                   spanning [SCORED_START - 8h, SCORED_END]
                                   inclusive (analyze_funding reads the frozen
                                   v8x window constants, so the span must be
                                   the REAL one)
  expected/{manifest,audit,gate}.json
                                   COMMITTED ENGINE OUTPUT: the exact bytes
                                   produced by
                                   scripts/v9_universe_audit.run_audit_from_bundle
                                   over this bundle (regenerated by this
                                   builder, never hand-written)
  fixture_entries.json             governance manifest fragment (one entry per
                                   file in this directory except itself)

HAND-COMPUTABLE DESIGN (windows are the REAL frozen v8x constants)
------------------------------------------------------------------
  PRE window    [2025-07-22T00:00Z, 2025-08-21T00:00Z)  = 30d  = 2880 slots
  SCORED window [2025-08-21T00:00Z, 2026-08-21T00:00Z)  = 365d = 35040 slots

  Every symbol gets SMALL single-session coverage:
    * one pre-window session: 96 slots = UTC day 0 of the pre window,
      its own parquet file  ->  days_with_bars_pre_window = 1 and the
      pre-window daily volume = 96 x (per-bar quote_volume) exactly;
    * one scored-window session: 96 slots = UTC day 0 of the scored window,
      its own parquet file.
  Slot stamping mirrors local capture (close minus 0.1 ms):
  ts_event = (slot_open + 900) * 1e9 - 100_000, which
  slot_opens_from_ts_event maps back to exactly slot_open.

  Census per GENERIC symbol (both sessions in separate files => two capture
  sessions per symbol):
    pre window    expected 2880; one missing run [slot 96 .. 2879] = 2784
                  slots, bounded by the pre session (before) and the scored
                  session (after)  ->  local_capture_boundary_between_sessions,
                  explained; unexplained = 0
    scored window expected 35040; one missing run [96 .. 35039] = 34944 slots,
                  bounded by the scored session (before), nothing after
                  ->  local_capture_ends_before_window_end, explained;
                  unexplained = 0
  AAAUSDT (rank 1) carries the DOCUMENTED capture-boundary case, mirroring the
  real ETHUSDT incident: a SECOND scored-window session (96 slots starting at
  scored-start + 30d) in its own file splits its scored-window holes into
    run1 [96 .. 2879]  = 2784  -> local_capture_boundary_between_sessions
    run2 [2976 .. 35039] = 32064 -> local_capture_ends_before_window_end
  scored gaps total = 34848, unexplained = 0.

  Hand totals over the 10 alts:
    slots_checked_total = 10 x (2880 + 35040)            = 379200
    gaps_found_total    = 9 x (2784+34944) + (2784+34848) = 377184
    unexplained_gaps_total = 0
  BTCUSDT (benchmark context only): same generic layout; censuses reported
  separately (2880/35040 slots; 2784/34944 gaps; 0 unexplained).

  Funding: 8h settlements from (SCORED_START - 8h) through SCORED END
  inclusive => 1097 rows/symbol, 1096 inside the exposure span; all intervals
  legal (8h), no duplicates, boundary coverage satisfied => complete.

  Listing age: onboardDate = scored-start - 400d => age 400.0d >= 365d ok.

REGENERATION
------------
    /path/to/python tests/fixtures/v9_universe_audit/build_fixture.py
  rewrites every file in this directory deterministically (same pyarrow major
  behavior).  The committed bytes are pinned by sha256 in fixture_entries.json
  AND in scripts/v9_universe_audit.FIXTURE_PINNED_MANIFEST_SHA256 (manifest
  only); if regeneration ever changes a digest, update the engine constant and
  re-commit -- tests fail loudly otherwise.
"""

from __future__ import annotations

import hashlib
import json
import sys
from decimal import Decimal
from pathlib import Path

THIS_DIR = Path(__file__).resolve().parent
REPO_ROOT = THIS_DIR.parents[2]
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))

from scripts.v8x_crypto_universe_selection import (  # noqa: E402
    BAR_INTERVAL_S,
    BTC_SYMBOL,
    PRE_END_S,
    PRE_START_S,
    SCORED_END_S,
    SCORED_START_S,
    utc_str,
)

# --------------------------------------------------------------------------- #
# Fixture construction parameters (all synthetic)
# --------------------------------------------------------------------------- #
AGENT = "fx-v9audit-fixture"
GENERATED_AT_UTC = "2026-08-26T00:00:00Z"
SLOTS_PER_SESSION = 96                    # 96 x 15m = one full UTC day
STAMP_NS_OFFSET = 100_000                 # close minus 0.1 ms (local-capture shape)
AAA_EXTRA_SCORED_SESSION_DAY = 30         # the documented ETH-like second session

# rank r (1..10) -> per-bar synthetic quote_volume string; volumes strictly
# decrease with rank so the pinned ranking order is self-consistent.
ALT_SYMBOLS = ["AAAUSDT", "BBBUSDT", "CCCUSDT", "DDDUSDT", "EEEUSDT",
               "FFFUSDT", "GGGUSDT", "HHHUSDT", "IIIUSDT", "JJJUSDT"]


def per_bar_volume(rank: int) -> str:
    return f"{300 - 10 * rank}.5"


BTC_PER_BAR_VOLUME = "500.5"

CATALOG_DIR = THIS_DIR / "catalog_root"
FUNDING_DIR = THIS_DIR / "funding"
EXPECTED_DIR = THIS_DIR / "expected"
PINNED_MANIFEST_PATH = THIS_DIR / "pinned_selection_manifest.json"
ENTRIES_PATH = THIS_DIR / "fixture_entries.json"
BUILDER_PATH = THIS_DIR / "build_fixture.py"

BAR_DIR_REL = "data/binance_bar"
INST_DIR_REL = "data/crypto_perpetual"
BAR_SUFFIX = "-15-MINUTE-LAST-EXTERNAL"
VENUE = "BINANCE"

# --------------------------------------------------------------------------- #
# Hand-computed expectations (derived from the construction, NOT the engine)
# --------------------------------------------------------------------------- #
PRE_SLOTS = (PRE_END_S - PRE_START_S) // BAR_INTERVAL_S        # 2880
SCORED_SLOTS = (SCORED_END_S - SCORED_START_S) // BAR_INTERVAL_S  # 35040
AAA_EXTRA_BASE = SCORED_START_S + AAA_EXTRA_SCORED_SESSION_DAY * 86400

HAND = {}  # symbol -> hand-computed facts


def _daily_volume_exact(sym: str) -> str:
    per_bar = BTC_PER_BAR_VOLUME if sym == BTC_SYMBOL else per_bar_volume(
        ALT_SYMBOLS.index(sym) + 1)
    return str(Decimal(per_bar) * SLOTS_PER_SESSION)


def _write_bar_parquet(path: Path, slot_opens: list[int], per_bar: str) -> None:
    import pyarrow as pa
    import pyarrow.parquet as pq

    ts_event = [(o + BAR_INTERVAL_S) * 1_000_000_000 - STAMP_NS_OFFSET
                for o in slot_opens]
    table = pa.table({
        "ts_event": pa.array(ts_event, type=pa.int64()),
        "quote_volume": pa.array([per_bar] * len(slot_opens), type=pa.string()),
    })
    path.parent.mkdir(parents=True, exist_ok=True)
    pq.write_table(table, path)


def _instrument_info_json() -> bytes:
    onboard_ms = (SCORED_START_S - 400 * 86400) * 1000
    info = {
        "quoteAsset": "USDT",
        "contractType": "PERPETUAL",
        "status": "TRADING",
        "onboardDate": onboard_ms,
        "filters": [
            {"filterType": "PRICE_FILTER", "tickSize": "0.01"},
            {"filterType": "LOT_SIZE", "stepSize": "1.0"},
            {"filterType": "MIN_NOTIONAL", "minNotional": "5.0"},
        ],
    }
    return json.dumps(info, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _write_instrument_parquet(path: Path, symbol: str) -> None:
    import pyarrow as pa
    import pyarrow.parquet as pq

    table = pa.table({
        "id": pa.array([f"{symbol}-PERP.{VENUE}"], type=pa.string()),
        "info": pa.array([_instrument_info_json()], type=pa.binary()),
    })
    path.parent.mkdir(parents=True, exist_ok=True)
    pq.write_table(table, path)


def _funding_rows(symbol: str) -> list[dict]:
    step_ms = 8 * 3600 * 1000
    start_ms = (SCORED_START_S - 8 * 3600) * 1000
    end_ms = SCORED_END_S * 1000
    rate = "0.00005000" if symbol == BTC_SYMBOL else "0.00010000"
    mark = "100000.0000" if symbol == BTC_SYMBOL else "1.0000000"
    return [{"fundingTime": t, "fundingRate": rate, "markPrice": mark}
            for t in range(start_ms, end_ms + 1, step_ms)]


def build_inputs() -> None:
    """Write every synthetic input file deterministically."""
    for rank, sym in enumerate(ALT_SYMBOLS, start=1):
        per_bar = per_bar_volume(rank)
        extra_scored = sym == ALT_SYMBOLS[0]  # AAAUSDT: documented ETH-like case
        # pre-window session (own file)
        _write_bar_parquet(
            CATALOG_DIR / BAR_DIR_REL / f"{sym}-PERP.{VENUE}{BAR_SUFFIX}" /
            f"{sym.lower()}-pre-0001.parquet",
            [PRE_START_S + k * BAR_INTERVAL_S for k in range(SLOTS_PER_SESSION)],
            per_bar)
        # scored-window session (own file)
        _write_bar_parquet(
            CATALOG_DIR / BAR_DIR_REL / f"{sym}-PERP.{VENUE}{BAR_SUFFIX}" /
            f"{sym.lower()}-scored-0001.parquet",
            [SCORED_START_S + k * BAR_INTERVAL_S for k in range(SLOTS_PER_SESSION)],
            per_bar)
        if extra_scored:
            _write_bar_parquet(
                CATALOG_DIR / BAR_DIR_REL / f"{sym}-PERP.{VENUE}{BAR_SUFFIX}" /
                f"{sym.lower()}-scored-0002.parquet",
                [AAA_EXTRA_BASE + k * BAR_INTERVAL_S
                 for k in range(SLOTS_PER_SESSION)],
                per_bar)
        _write_instrument_parquet(
            CATALOG_DIR / INST_DIR_REL / f"{sym}-PERP.{VENUE}" /
            "instrument-0001.parquet", sym)
        rows = _funding_rows(sym)
        fp = FUNDING_DIR / sym / "funding.json"
        fp.parent.mkdir(parents=True, exist_ok=True)
        fp.write_text(json.dumps({"symbol": sym, "rows": rows}, indent=1,
                                 sort_keys=True) + "\n")
        scored_gaps = (2784 + 32064) if extra_scored else 34944
        HAND[sym] = {
            "rank": rank,
            "days_with_bars_pre_window": 1,
            "daily_volume_exact": _daily_volume_exact(sym),
            "census_pre_window_gaps": 2784,
            "census_scored_window_gaps": scored_gaps,
            "census_scored_window_unexplained": 0,
            "funding_rows": len(rows),
            "funding_complete": True,
        }

    # BTCUSDT: benchmark context only, generic layout
    _write_bar_parquet(
        CATALOG_DIR / BAR_DIR_REL / f"{BTC_SYMBOL}-PERP.{VENUE}{BAR_SUFFIX}" /
        "btc-pre-0001.parquet",
        [PRE_START_S + k * BAR_INTERVAL_S for k in range(SLOTS_PER_SESSION)],
        BTC_PER_BAR_VOLUME)
    _write_bar_parquet(
        CATALOG_DIR / BAR_DIR_REL / f"{BTC_SYMBOL}-PERP.{VENUE}{BAR_SUFFIX}" /
        "btc-scored-0001.parquet",
        [SCORED_START_S + k * BAR_INTERVAL_S for k in range(SLOTS_PER_SESSION)],
        BTC_PER_BAR_VOLUME)
    _write_instrument_parquet(
        CATALOG_DIR / INST_DIR_REL / f"{BTC_SYMBOL}-PERP.{VENUE}" /
        "instrument-0001.parquet", BTC_SYMBOL)
    rows = _funding_rows(BTC_SYMBOL)
    fp = FUNDING_DIR / BTC_SYMBOL / "funding.json"
    fp.parent.mkdir(parents=True, exist_ok=True)
    fp.write_text(json.dumps({"symbol": BTC_SYMBOL, "rows": rows}, indent=1,
                             sort_keys=True) + "\n")
    HAND[BTC_SYMBOL] = {
        "rank": None,
        "days_with_bars_pre_window": 1,
        "daily_volume_exact": _daily_volume_exact(BTC_SYMBOL),
        "census_pre_window_gaps": 2784,
        "census_scored_window_gaps": 34944,
        "census_scored_window_unexplained": 0,
        "funding_rows": len(rows),
        "funding_complete": True,
    }


def build_pinned_manifest() -> None:
    chosen = []
    for sym in ALT_SYMBOLS:
        h = HAND[sym]
        chosen.append({
            "rank": h["rank"],
            "symbol": sym,
            "instrument_id": f"{sym}-PERP.{VENUE}",
            "median_daily_quote_volume_pre_window_usdt":
                float(h["daily_volume_exact"]),
            "days_with_bars_pre_window": h["days_with_bars_pre_window"],
            "census_pre_window_gaps": h["census_pre_window_gaps"],
            "census_scored_window_gaps": h["census_scored_window_gaps"],
            "census_scored_window_unexplained": h["census_scored_window_unexplained"],
            "funding_held_exposure_complete": h["funding_complete"],
        })
    candidates = []
    for sym in ALT_SYMBOLS + [BTC_SYMBOL]:
        h = HAND[sym]
        candidates.append({
            "symbol": sym,
            "instrument_id": f"{sym}-PERP.{VENUE}",
            "volume": {
                "days_with_bars_pre_window": h["days_with_bars_pre_window"],
                "median_daily_quote_volume_usdt_exact": h["daily_volume_exact"],
                "median_daily_quote_volume_usdt": float(h["daily_volume_exact"]),
            },
            "note": ("synthetic fixture candidate; only the pinned volume fields "
                     "the V9 engine revalidates are materialized"),
        })
    manifest = {
        "schema_version": "2.0.0",
        "agent": AGENT,
        "generated_at_utc": GENERATED_AT_UTC,
        "performance_blind": True,
        "fixture": {
            "class": "SCHEMA_MINIMAL",
            "input_fixture_class": "SYNTHETIC_HAND_COMPUTED",
            "license_authority": "repo-authored synthetic",
            "contains_real_provider_payload": False,
            "contains_secret": False,
            "replica_of": "data/v8x_manifests/crypto_universe_selection.json",
            "builder": "tests/fixtures/v9_universe_audit/build_fixture.py",
            "symbols": {"chosen_alts": ALT_SYMBOLS,
                        "benchmark_context_only": BTC_SYMBOL},
            "documented_gap_class": {
                "cause": "local_capture_boundary_between_sessions",
                "carrier": ALT_SYMBOLS[0],
                "mirrors": ("the real ETHUSDT scored-window capture-boundary run "
                            "of the committed historical artifacts"),
                "hand_slots": 2784,
            },
            "hand_computation": {
                "pre_window_slots": PRE_SLOTS,
                "scored_window_slots": SCORED_SLOTS,
                "slots_per_session": SLOTS_PER_SESSION,
                "per_symbol_pre_gaps": 2784,
                "per_symbol_scored_gaps_generic": 34944,
                "alts_slots_checked_total": 10 * (PRE_SLOTS + SCORED_SLOTS),
                "alts_gaps_found_total": 9 * (2784 + 34944) + (2784 + 34848),
                "alts_unexplained_gaps_total": 0,
                "funding_rows_per_symbol": HAND[ALT_SYMBOLS[0]]["funding_rows"],
                "funding_settlements_in_exposure_span": HAND[ALT_SYMBOLS[0]]["funding_rows"] - 1,
                "listing_age_days_at_first_possible_exposure": 400.0,
            },
        },
        "selection_window": {
            "start_utc": utc_str(PRE_START_S),
            "end_utc": utc_str(PRE_END_S),
            "note": "fixture replica of the frozen V8 selection window contract",
        },
        "scored_window": {
            "start_utc": utc_str(SCORED_START_S),
            "end_utc": utc_str(SCORED_END_S),
            "note": "fixture replica of the frozen V8 scored window contract",
        },
        "ranking_rule": "median_daily_quote_volume_pre_window_only",
        "btc_excluded": True,
        "btc_exclusion_note": (
            f"{BTC_SYMBOL} is benchmark measurement-only in this fixture and is "
            "excluded from the ranked/traded universe"),
        "rule_constants": {
            "catalog_root": "tests/fixtures/v9_universe_audit/catalog_root",
            "bar_dir_rel": BAR_DIR_REL,
            "instrument_dir_rel": INST_DIR_REL,
            "funding_root": "tests/fixtures/v9_universe_audit/funding",
            "venue": VENUE,
            "bar_spec_suffix": BAR_SUFFIX,
            "bar_interval_seconds": BAR_INTERVAL_S,
            "top_n": 10,
        },
        "candidates_evaluated": candidates,
        "chosen_top10": chosen,
        "not_selected_eligible": [],
        "not_selected_eligible_note": ("synthetic fixture: no unselected-eligible "
                                       "pool is materialized"),
        "verdict": "SYNTHETIC_FIXTURE_REPLICA_OF_V8X_TOP10_ELIGIBLE",
    }
    PINNED_MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, ensure_ascii=False) + "\n")


def build_expected_artifacts() -> dict:
    """Run the ENGINE over the committed bundle; commit its exact bytes."""
    from scripts.v9_universe_audit import (
        FIXTURE_PINNED_MANIFEST_SHA256,
        fixture_descriptor,
        load_inputs,
        run_audit_from_bundle,
        sha256_file,
        write_json,
    )

    actual_sha = sha256_file(PINNED_MANIFEST_PATH)
    if FIXTURE_PINNED_MANIFEST_SHA256 != actual_sha:
        raise SystemExit(
            "scripts/v9_universe_audit.FIXTURE_PINNED_MANIFEST_SHA256 does not "
            f"match {PINNED_MANIFEST_PATH} sha256={actual_sha}; update the "
            "engine constant and re-run this builder.")

    loaded = load_inputs(fixture_descriptor(repo_root=REPO_ROOT))
    if not loaded.available:  # pragma: no cover - committed fixture exists
        raise SystemExit(f"fixture inputs unavailable: {loaded.missing}")
    res = run_audit_from_bundle(loaded)

    # in-builder sanity: the engine must reproduce the hand computations
    gate = res["gate"]
    audit = res["audit"]
    assert gate["status"] == "PASS", [c for c in gate["checks"] if not c["ok"]]
    gc = audit["gap_census"]
    assert gc["slots_checked_total"] == 10 * (PRE_SLOTS + SCORED_SLOTS)
    assert gc["gaps_found_total"] == 9 * (2784 + 34944) + (2784 + 34848)
    assert gc["unexplained_gaps_total"] == 0
    assert any(r["cause"] == "local_capture_boundary_between_sessions"
               for r in gc["documented_gap_classes_present"])
    assert audit["funding_coverage"]["all_selected_complete"] is True
    assert [c["symbol"] for c in res["manifest"]["selected_symbols"]] == ALT_SYMBOLS
    for sym, block in gc["per_symbol"].items():
        assert block["pre_window"]["gaps_found"] == HAND[sym]["census_pre_window_gaps"]
        assert block["scored_window"]["gaps_found"] == HAND[sym]["census_scored_window_gaps"]
        assert block["scored_window"]["unexplained_gaps"] == 0

    EXPECTED_DIR.mkdir(parents=True, exist_ok=True)
    write_json(EXPECTED_DIR / "manifest.json", res["manifest"])
    write_json(EXPECTED_DIR / "audit.json", res["audit"])
    write_json(EXPECTED_DIR / "gate.json", res["gate"])
    return res


def build_fixture_entries() -> None:
    """Governance-manifest fragment: one entry per file in this directory
    (except this index file itself, which cannot hash itself)."""
    classes = {
        "build_fixture.py": "fixture_builder_script",
        "pinned_selection_manifest.json": "SCHEMA_MINIMAL",
    }
    semantics = {
        "build_fixture.py":
            "deterministic regeneration tool + hand-computation documentation "
            "for this fixture",
        "pinned_selection_manifest.json":
            "repo-authored synthetic SCHEMA_MINIMAL replica of "
            "data/v8x_manifests/crypto_universe_selection.json with "
            "hand-computed chosen_top10 / candidates_evaluated values",
        "expected/":
            "byte-pinned output of scripts/v9_universe_audit."
            "run_audit_from_bundle over the committed fixture bundle",
        "catalog_root/data/binance_bar/":
            "SYNTHETIC_HAND_COMPUTED 15m bars (ts_event int64 ns, quote_volume "
            "string) on the REAL frozen window grid, single-session coverage "
            "so every census is hand-computable; no real provider payload",
        "catalog_root/data/crypto_perpetual/":
            "SYNTHETIC_HAND_COMPUTED instrument definition (id + "
            "exchangeInfo-shaped info JSON: quoteAsset USDT, contractType "
            "PERPETUAL, status TRADING, onboardDate scored-start-400d)",
        "funding/":
            "SYNTHETIC_HAND_COMPUTED complete 8h funding settlements spanning "
            "[SCORED_START-8h, SCORED_END] inclusive (analyze_funding reads "
            "the frozen v8x window constants)",
    }

    def classify(rel: str) -> str:
        if rel in classes:
            return classes[rel]
        if rel.startswith("expected/"):
            return "expected_engine_artifact"
        if rel.startswith("catalog_root/data/binance_bar/"):
            return "SYNTHETIC_HAND_COMPUTED"
        if rel.startswith("catalog_root/data/crypto_perpetual/"):
            return "SYNTHETIC_HAND_COMPUTED"
        if rel.startswith("funding/"):
            return "SYNTHETIC_HAND_COMPUTED"
        raise AssertionError(f"unclassified fixture file: {rel}")

    def semantics_for(rel: str) -> str:
        if rel.startswith("expected/"):
            return semantics["expected/"]
        for prefix, text in semantics.items():
            if rel.startswith(prefix):
                return text
        raise AssertionError(rel)

    files = sorted(
        p for p in THIS_DIR.rglob("*")
        if p.is_file() and p != ENTRIES_PATH
    )
    entries = []
    for p in sorted(files):
        rel_from_fixture = p.relative_to(THIS_DIR).as_posix()
        rel_repo = p.relative_to(REPO_ROOT).as_posix()
        entry_id = "fx-v9audit-" + rel_from_fixture.replace("/", "-").replace(
            ".", "-").replace("_", "-")
        entries.append({
            "fixture_id": entry_id,
            "path": rel_repo,
            "class": classify(rel_from_fixture),
            "purpose": semantics_for(rel_from_fixture),
            "sha256": hashlib.sha256(p.read_bytes()).hexdigest(),
            "license_authority": "repo-authored synthetic",
            "contains_real_provider_payload": False,
            "contains_secret": False,
            "expected_consumers": [
                "scripts/v9_universe_audit.py",
                "scripts/v9_universe_audit_tier_r.py",
                "tests/test_v9_universe_audit.py",
            ],
            "expected_semantics": semantics_for(rel_from_fixture),
        })
    payload = {
        "cycle": "MARKET-DATA-PLANE-V2R1",
        "lane": "A3",
        "note": ("fragment for merge into tests/fixtures/"
                 "governance_fixture_manifest.json by the cycle controller; "
                 "one entry per file under tests/fixtures/v9_universe_audit/ "
                 "except this index (a file cannot contain its own hash)"),
        "entries": entries,
    }
    ENTRIES_PATH.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n")


def main() -> int:
    inputs_only = "--inputs-only" in sys.argv
    build_inputs()
    build_pinned_manifest()
    manifest_sha = hashlib.sha256(PINNED_MANIFEST_PATH.read_bytes()).hexdigest()
    print("pinned_selection_manifest.json sha256:", manifest_sha)
    if inputs_only:
        print("inputs written; expected artifacts NOT generated")
        return 0
    res = build_expected_artifacts()
    build_fixture_entries()
    n_entries = len(json.loads(ENTRIES_PATH.read_text())["entries"])
    print("gate status:", res["gate"]["status"])
    print("gap census:", res["gate"]["gap_census_totals"])
    print("fixture entries:", n_entries)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
